{
  "name": "DP800系列可编程直流电源",
  "name_en": "DP800 Series Programmable DC Power Supply",
  "manufacturer": "RIGOL",
  "description": "台式多路可编程直流电源，用于为实验电路、器件和原型系统提供稳定可调的电压与电流输出，并可测量输出电压、电流和功率；部分型号支持远端电压补偿。",
  "description_en": "A benchtop multi-channel programmable DC power supply used to provide stable, adjustable voltage and current to laboratory circuits, devices, and prototype systems, with measurement of output voltage, current, and power; some models support remote sensing.",
  "tag_hints": [
    "programmable DC power supply",
    "bench power supply",
    "multi-channel output",
    "voltage/current sourcing",
    "output measurement",
    "remote sensing",
    "linear power supply"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电源并默认选择通道1。",
      "description_en": "Initialize the power supply and select channel 1 by default."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁前面板按键操作。",
      "description_en": "Lock or unlock the front-panel controls."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量当前所选通道的输出电流。",
      "description_en": "Measure the output current of the currently selected channel."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量当前所选通道的输出功率。",
      "description_en": "Measure the output power of the currently selected channel."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量当前所选通道的输出电压。",
      "description_en": "Measure the output voltage of the currently selected channel."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "开启或关闭远端电压补偿（仅部分型号支持，如DP811）。",
      "description_en": "Enable or disable remote sensing (supported only on some models, such as the DP811)."
    },
    {
      "action_name": "auto-select_channel",
      "description": "选择电源输出通道。",
      "description_en": "Select the output channel."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置当前所选通道的电流设定值。",
      "description_en": "Set the current setpoint of the currently selected channel."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置当前所选通道的电压设定值。",
      "description_en": "Set the voltage setpoint of the currently selected channel."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭当前所选通道的输出。",
      "description_en": "Turn the output of the currently selected channel on or off."
    }
  ]
}

